const lines=require('fs').readFileSync(0,'utf8').split('\n');
const parts=lines[0].trim().split(/\s+/).map(Number);
const n=parts[0], t=parts[1];
// dp[prev][cur][h][v]
function makeDP(){
  const a=[];
  for(let i=0;i<5;i++){a.push([]);for(let j=0;j<5;j++){a[i].push([]);for(let h=0;h<=11;h++){a[i][j].push(new Array(12).fill(0));}}}
  return a;
}
let dp=makeDP();
for(let a=1;a<=4;a++)for(let b=1;b<=4;b++){if(a!==b)dp[a][b][0][0]=1;}
for(let i=3;i<=n;i++){
  const nd=makeDP();
  for(let p=1;p<=4;p++)for(let c=1;c<=4;c++){
    if(p===c)continue;
    for(let h=0;h<=t;h++)for(let v=0;v<=t;v++){
      const val=dp[p][c][h][v];
      if(val===0)continue;
      for(let x=1;x<=4;x++){
        if(x===c)continue;
        let nh=h+((p<c&&c>x)?1:0);
        let nv=v+((p>c&&c<x)?1:0);
        if(nh>t||nv>t)continue;
        nd[c][x][nh][nv]+=val;
      }
    }
  }
  dp=nd;
}
let ans=0;
if(t-1>=0){
  for(let p=1;p<=4;p++)for(let c=1;c<=4;c++){ans+=dp[p][c][t][t-1];}
}
console.log(String(ans));
